    """Extend each interior mark from its matching edge band and paired band."""
    from collections import Counter

    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def runs(values):
        found = []
        i = 0
        while i < len(values):
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if values[i] != background and j - i >= 2:
                found.append((values[i], i, j))
            i = j
        return found

    # Find equal-length matching colored bars on opposite borders.
    pair = None
    for a in runs(grid[0]):
        for b in runs(grid[-1]):
            if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                pair = ('vertical', a, b)
                break
        if pair:
            break
    if pair is None:
        left = runs([grid[r][0] for r in range(h)])
        right = runs([grid[r][-1] for r in range(h)])
        for a in left:
            for b in right:
                if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                    pair = ('horizontal', a, b)
                    break
            if pair:
                break
    if pair is None:
        return g

    orientation, first, second = pair
    bar_color = first[0]
    marks = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (background, bar_color)]

    for r, c, color in marks:
        if orientation == 'vertical':
            if first[1] <= c < first[2]:  # mark aligns with top bar
                offset = c - first[1]
                mate = second[1] + offset
                for rr in range(1, r):
                    g[rr][c] = color
                for rr in range(1, h - 1):
                    g[rr][mate] = color
            elif second[1] <= c < second[2]:  # mark aligns with bottom bar
                offset = c - second[1]
                mate = first[1] + offset
                for rr in range(r + 1, h - 1):
                    g[rr][c] = color
                for rr in range(1, h - 1):
                    g[rr][mate] = color
            else:
                continue
        else:
            if first[1] <= r < first[2]:  # mark aligns with left bar
